import { __decorate } from "tslib";
import { Component, ViewChild } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Chart, registerables } from 'chart.js';
Chart.register(...registerables);
let AdvancedAnalyticsComponent = class AdvancedAnalyticsComponent {
  constructor(analyticsService, employeeService, jobDescriptionService, jobOfferService) {
    this.analyticsService = analyticsService;
    this.employeeService = employeeService;
    this.jobDescriptionService = jobDescriptionService;
    this.jobOfferService = jobOfferService;
    // Données réelles du projet
    this.employees = [];
    this.jobDescriptions = [];
    this.jobOffers = [];
    // Analytics calculées
    this.analyticsOverview = null;
    this.departmentStats = [];
    this.contractStats = [];
    this.skillsDemand = [];
    this.realTimeStats = {};
    // Charts
    this.departmentChart = null;
    this.contractChart = null;
    this.skillsChart = null;
    this.trendsChart = null;
    this.employeePositionChart = null;
    this.skillTypeChart = null;
    // Filters
    this.filters = {};
    this.selectedPeriod = 'month';
    this.selectedMetric = 'applications';
    // States
    this.loading = true;
    this.errorMessage = null;
    this.activeTab = 'overview';
  }
  ngOnInit() {
    this.loadRealData();
  }
  ngAfterViewInit() {
    // Charts will be created after data is loaded
  }
  ngOnDestroy() {
    this.destroyAllCharts();
  }
  loadRealData() {
    this.loading = true;
    this.errorMessage = null;
    console.log('🔄 Chargement des données réelles...');
    Promise.all([this.employeeService.getEmployees().toPromise(), this.jobDescriptionService.getJobDescriptions().toPromise(), this.jobOfferService.getJobOffers().toPromise()]).then(([employees, jobDescriptions, jobOffers]) => {
      console.log('✅ Données chargées:', {
        employees: employees?.length || 0,
        jobDescriptions: jobDescriptions?.length || 0,
        jobOffers: jobOffers?.length || 0
      });
      this.employees = employees || [];
      this.jobDescriptions = jobDescriptions || [];
      this.jobOffers = jobOffers || [];
      this.calculateRealAnalytics();
      this.loading = false;
      // Créer les graphiques après un court délai
      setTimeout(() => {
        this.createChartsForActiveTab();
      }, 100);
    }).catch(err => {
      console.error('❌ Erreur lors du chargement des données:', err);
      this.errorMessage = 'Erreur lors du chargement des données. Vérifiez que le backend est en cours d\'exécution.';
      this.loading = false;
    });
  }
  calculateRealAnalytics() {
    console.log('📊 Calcul des analytics réelles...');
    // Statistiques de base réelles
    this.realTimeStats = {
      totalEmployees: this.employees.length,
      totalJobDescriptions: this.jobDescriptions.length,
      totalJobOffers: this.jobOffers.length,
      publishedOffers: this.jobOffers.filter(offer => offer.status === 'published').length,
      draftOffers: this.jobOffers.filter(offer => offer.status === 'draft').length,
      closedOffers: this.jobOffers.filter(offer => offer.status === 'closed').length,
      totalSkills: this.calculateTotalUniqueSkills(),
      averageSkillsPerEmployee: this.calculateAverageSkillsPerEmployee(),
      mostCommonPosition: this.getMostCommonPosition(),
      mostActiveFiliere: this.getMostActiveFiliere()
    };
    // Calculer les vraies statistiques
    this.calculateRealDepartmentStats();
    this.calculateRealContractStats();
    this.calculateRealSkillsDemand();
    console.log('✅ Analytics calculées:', this.realTimeStats);
  }
  calculateTotalUniqueSkills() {
    const uniqueSkills = new Set();
    this.employees.forEach(emp => {
      const skills = emp.skills || emp.EmployeeSkills || [];
      skills.forEach(skill => {
        if (skill.skill_id) {
          uniqueSkills.add(skill.skill_id);
        }
      });
    });
    return uniqueSkills.size;
  }
  calculateAverageSkillsPerEmployee() {
    if (this.employees.length === 0) return 0;
    const totalSkills = this.employees.reduce((sum, emp) => {
      const skills = emp.skills || emp.EmployeeSkills || [];
      return sum + skills.length;
    }, 0);
    return Math.round(totalSkills / this.employees.length * 10) / 10;
  }
  calculateRealDepartmentStats() {
    const departmentMap = new Map();
    // Grouper les employés par département/position
    this.employees.forEach(emp => {
      const dept = emp.department || emp.position || 'Non défini';
      if (!departmentMap.has(dept)) {
        departmentMap.set(dept, {
          employees: [],
          jobDescriptions: [],
          jobOffers: [],
          totalSkills: 0
        });
      }
      const deptData = departmentMap.get(dept);
      deptData.employees.push(emp);
      // Compter les compétences
      const skills = emp.skills || emp.EmployeeSkills || [];
      deptData.totalSkills += skills.length;
    });
    // Grouper les fiches de poste par filière
    this.jobDescriptions.forEach(job => {
      const dept = job.filiere_activite || 'Non défini';
      if (!departmentMap.has(dept)) {
        departmentMap.set(dept, {
          employees: [],
          jobDescriptions: [],
          jobOffers: [],
          totalSkills: 0
        });
      }
      departmentMap.get(dept).jobDescriptions.push(job);
    });
    // Grouper les offres d'emploi
    this.jobOffers.forEach(offer => {
      const jobDesc = this.jobDescriptions.find(job => job.id === offer.job_description_id);
      const dept = jobDesc?.filiere_activite || 'Non défini';
      if (!departmentMap.has(dept)) {
        departmentMap.set(dept, {
          employees: [],
          jobDescriptions: [],
          jobOffers: [],
          totalSkills: 0
        });
      }
      departmentMap.get(dept).jobOffers.push(offer);
    });
    this.departmentStats = Array.from(departmentMap.entries()).map(([dept, data]) => {
      const publishedOffers = data.jobOffers.filter(o => o.status === 'published').length;
      const totalOffers = data.jobOffers.length;
      return {
        department: dept,
        total_applications: totalOffers,
        successful_applications: publishedOffers,
        success_rate: totalOffers > 0 ? publishedOffers / totalOffers * 100 : 0,
        average_time_to_hire: data.employees.length > 0 ? data.employees.reduce((sum, emp) => {
          const hireDate = new Date(emp.hire_date);
          const daysSinceHire = Math.floor((Date.now() - hireDate.getTime()) / (1000 * 60 * 60 * 24));
          return sum + Math.min(daysSinceHire, 365); // Cap à 1 an
        }, 0) / data.employees.length : 0,
        top_skills_requested: this.getTopSkillsForDepartment(dept)
      };
    }).filter(dept => dept.total_applications > 0 || dept.successful_applications > 0).sort((a, b) => b.total_applications - a.total_applications);
  }
  getTopSkillsForDepartment(department) {
    const skillMap = new Map();
    // Analyser les compétences requises dans les fiches de ce département
    this.jobDescriptions.filter(job => job.filiere_activite === department).forEach(job => {
      if (job.requiredSkills) {
        job.requiredSkills.forEach(reqSkill => {
          const skillId = reqSkill.skill_id;
          const skillName = reqSkill.skill?.name || `Skill ${skillId}`;
          if (!skillMap.has(skillId)) {
            skillMap.set(skillId, {
              name: skillName,
              count: 0
            });
          }
          skillMap.get(skillId).count++;
        });
      }
    });
    return Array.from(skillMap.entries()).map(([skillId, data]) => ({
      skill_id: skillId,
      skill_name: data.name,
      demand_count: data.count,
      success_rate_with_skill: this.calculateSkillSuccessRate(skillId),
      average_level_required: this.calculateAverageRequiredLevel(skillId)
    })).sort((a, b) => b.demand_count - a.demand_count).slice(0, 5);
  }
  calculateSkillSuccessRate(skillId) {
    // Calculer le taux de succès basé sur les employés qui ont cette compétence
    const employeesWithSkill = this.employees.filter(emp => {
      const skills = emp.skills || emp.EmployeeSkills || [];
      return skills.some(skill => skill.skill_id === skillId);
    }).length;
    const totalEmployees = this.employees.length;
    return totalEmployees > 0 ? employeesWithSkill / totalEmployees * 100 : 0;
  }
  calculateAverageRequiredLevel(skillId) {
    const requiredLevels = [];
    this.jobDescriptions.forEach(job => {
      if (job.requiredSkills) {
        const skillReq = job.requiredSkills.find(req => req.skill_id === skillId);
        if (skillReq && skillReq.skill_level?.value) {
          requiredLevels.push(skillReq.skill_level.value);
        }
      }
    });
    return requiredLevels.length > 0 ? requiredLevels.reduce((sum, level) => sum + level, 0) / requiredLevels.length : 0;
  }
  calculateRealContractStats() {
    const contractMap = new Map();
    // Grouper les offres par type de contrat
    this.jobOffers.forEach(offer => {
      const contractType = offer.contract_type || 'CDI';
      if (!contractMap.has(contractType)) {
        contractMap.set(contractType, []);
      }
      contractMap.get(contractType).push(offer);
    });
    this.contractStats = Array.from(contractMap.entries()).map(([type, offers]) => {
      const publishedOffers = offers.filter(o => o.status === 'published').length;
      const totalOffers = offers.length;
      // Calculer les salaires moyens réels
      const offersWithSalary = offers.filter(o => o.salary_min && o.salary_max);
      const avgSalaryMin = offersWithSalary.length > 0 ? Math.round(offersWithSalary.reduce((sum, o) => sum + (o.salary_min || 0), 0) / offersWithSalary.length) : 0;
      const avgSalaryMax = offersWithSalary.length > 0 ? Math.round(offersWithSalary.reduce((sum, o) => sum + (o.salary_max || 0), 0) / offersWithSalary.length) : 0;
      return {
        contract_type: type,
        total_applications: totalOffers,
        successful_applications: publishedOffers,
        success_rate: totalOffers > 0 ? publishedOffers / totalOffers * 100 : 0,
        average_salary_min: avgSalaryMin,
        average_salary_max: avgSalaryMax,
        most_requested_skills: this.getMostRequestedSkillsForContract(type)
      };
    }).filter(stat => stat.total_applications > 0);
  }
  getMostRequestedSkillsForContract(contractType) {
    const skillMap = new Map();
    // Analyser les compétences dans les offres de ce type de contrat
    this.jobOffers.filter(offer => offer.contract_type === contractType).forEach(offer => {
      const jobDesc = this.jobDescriptions.find(job => job.id === offer.job_description_id);
      if (jobDesc?.requiredSkills) {
        jobDesc.requiredSkills.forEach(reqSkill => {
          const skillName = reqSkill.skill?.name || `Skill ${reqSkill.skill_id}`;
          skillMap.set(skillName, (skillMap.get(skillName) || 0) + 1);
        });
      }
    });
    return Array.from(skillMap.entries()).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([name]) => name);
  }
  calculateRealSkillsDemand() {
    const skillDemandMap = new Map();
    // Analyser les compétences requises dans les fiches de poste
    this.jobDescriptions.forEach(job => {
      if (job.requiredSkills) {
        job.requiredSkills.forEach(reqSkill => {
          const skillId = reqSkill.skill_id;
          const skillName = reqSkill.skill?.name || `Skill ${skillId}`;
          const requiredLevel = reqSkill.skill_level?.value || 0;
          if (!skillDemandMap.has(skillId)) {
            skillDemandMap.set(skillId, {
              name: skillName,
              demandCount: 0,
              employeeCount: 0,
              totalRequiredLevel: 0,
              requirementCount: 0
            });
          }
          const skillData = skillDemandMap.get(skillId);
          skillData.demandCount++;
          skillData.totalRequiredLevel += requiredLevel;
          skillData.requirementCount++;
        });
      }
    });
    // Compter les employés qui ont ces compétences
    this.employees.forEach(emp => {
      const empSkills = emp.skills || emp.EmployeeSkills || [];
      empSkills.forEach(empSkill => {
        const skillId = empSkill.skill_id;
        if (skillDemandMap.has(skillId)) {
          skillDemandMap.get(skillId).employeeCount++;
        }
      });
    });
    this.skillsDemand = Array.from(skillDemandMap.entries()).map(([skillId, data]) => ({
      skill_id: skillId,
      skill_name: data.name,
      demand_count: data.demandCount,
      success_rate_with_skill: this.employees.length > 0 ? data.employeeCount / this.employees.length * 100 : 0,
      average_level_required: data.requirementCount > 0 ? data.totalRequiredLevel / data.requirementCount : 0
    })).sort((a, b) => b.demand_count - a.demand_count).slice(0, 15);
  }
  setActiveTab(tab) {
    this.activeTab = tab;
    // Recréer les graphiques pour l'onglet actif
    setTimeout(() => {
      this.createChartsForActiveTab();
    }, 100);
  }
  applyFilters() {
    console.log('🔍 Application des filtres:', this.filters);
    this.loadRealData();
  }
  clearFilters() {
    this.filters = {};
    this.loadRealData();
  }
  refreshData() {
    console.log('🔄 Actualisation des données...');
    this.loadRealData();
  }
  createChartsForActiveTab() {
    // Détruire les graphiques existants
    this.destroyAllCharts();
    switch (this.activeTab) {
      case 'overview':
        this.createOverviewCharts();
        break;
      case 'departments':
        this.createDepartmentChart();
        break;
      case 'contracts':
        this.createContractChart();
        break;
      case 'skills':
        this.createSkillsChart();
        this.createSkillTypeChart();
        break;
      case 'trends':
        this.createTrendsChart();
        break;
      case 'employees':
        this.createEmployeePositionChart();
        break;
    }
  }
  createOverviewCharts() {
    this.createDepartmentChart();
    this.createContractChart();
  }
  createDepartmentChart() {
    if (this.departmentChart) {
      this.departmentChart.destroy();
      this.departmentChart = null;
    }
    const ctx = this.departmentChartRef?.nativeElement?.getContext('2d');
    if (ctx && this.departmentStats.length > 0) {
      console.log('📊 Création du graphique départements avec', this.departmentStats.length, 'départements');
      this.departmentChart = new Chart(ctx, {
        type: 'bar',
        data: {
          labels: this.departmentStats.map(d => d.department),
          datasets: [{
            label: 'Employés',
            data: this.departmentStats.map(d => {
              return this.employees.filter(emp => (emp.department || emp.position) === d.department).length;
            }),
            backgroundColor: '#3B82F6',
            borderColor: '#2563EB',
            borderWidth: 1
          }, {
            label: 'Fiches de poste',
            data: this.departmentStats.map(d => {
              return this.jobDescriptions.filter(job => job.filiere_activite === d.department).length;
            }),
            backgroundColor: '#10B981',
            borderColor: '#059669',
            borderWidth: 1
          }, {
            label: 'Offres d\'emploi',
            data: this.departmentStats.map(d => {
              return this.jobOffers.filter(offer => {
                const jobDesc = this.jobDescriptions.find(job => job.id === offer.job_description_id);
                return jobDesc?.filiere_activite === d.department;
              }).length;
            }),
            backgroundColor: '#F59E0B',
            borderColor: '#D97706',
            borderWidth: 1
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          scales: {
            y: {
              beginAtZero: true,
              ticks: {
                stepSize: 1
              }
            }
          },
          plugins: {
            legend: {
              position: 'top'
            },
            tooltip: {
              mode: 'index',
              intersect: false
            }
          }
        }
      });
    }
  }
  createContractChart() {
    if (this.contractChart) {
      this.contractChart.destroy();
      this.contractChart = null;
    }
    const ctx = this.contractChartRef?.nativeElement?.getContext('2d');
    if (ctx && this.contractStats.length > 0) {
      console.log('📊 Création du graphique contrats avec', this.contractStats.length, 'types');
      this.contractChart = new Chart(ctx, {
        type: 'doughnut',
        data: {
          labels: this.contractStats.map(c => c.contract_type),
          datasets: [{
            data: this.contractStats.map(c => c.total_applications),
            backgroundColor: ['#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6'],
            hoverBackgroundColor: ['#2563EB', '#059669', '#D97706', '#DC2626', '#7C3AED'],
            borderWidth: 2,
            borderColor: '#ffffff'
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: {
              position: 'bottom'
            },
            tooltip: {
              callbacks: {
                label: context => {
                  const label = context.label || '';
                  const value = context.parsed;
                  const total = context.dataset.data.reduce((sum, current) => sum + current, 0);
                  const percentage = total > 0 ? (value / total * 100).toFixed(1) : 0;
                  return `${label}: ${value} offres (${percentage}%)`;
                }
              }
            }
          }
        }
      });
    }
  }
  createSkillsChart() {
    if (this.skillsChart) {
      this.skillsChart.destroy();
      this.skillsChart = null;
    }
    const ctx = this.skillsChartRef?.nativeElement?.getContext('2d');
    if (ctx && this.skillsDemand.length > 0) {
      console.log('📊 Création du graphique compétences avec', this.skillsDemand.length, 'compétences');
      const topSkills = this.skillsDemand.slice(0, 10);
      this.skillsChart = new Chart(ctx, {
        type: 'bar',
        data: {
          labels: topSkills.map(s => s.skill_name),
          datasets: [{
            label: 'Demande dans les fiches de poste',
            data: topSkills.map(s => s.demand_count),
            backgroundColor: '#8B5CF6',
            borderColor: '#7C3AED',
            borderWidth: 1
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          indexAxis: 'y',
          scales: {
            x: {
              beginAtZero: true,
              ticks: {
                stepSize: 1
              }
            }
          },
          plugins: {
            legend: {
              display: false
            },
            tooltip: {
              callbacks: {
                label: context => {
                  return `Demandée dans ${context.parsed.x} fiche(s) de poste`;
                }
              }
            }
          }
        }
      });
    }
  }
  createSkillTypeChart() {
    if (this.skillTypeChart) {
      this.skillTypeChart.destroy();
      this.skillTypeChart = null;
    }
    const ctx = this.skillTypeChartRef?.nativeElement?.getContext('2d');
    if (ctx && this.employees.length > 0) {
      console.log('📊 Création du graphique types de compétences');
      // Analyser la répartition des types de compétences
      const skillTypeMap = new Map();
      this.employees.forEach(emp => {
        const skills = emp.skills || emp.EmployeeSkills || [];
        skills.forEach(empSkill => {
          const skillType = empSkill.skill?.type?.type_name || empSkill.skill?.type?.type_name || 'Non défini';
          skillTypeMap.set(skillType, (skillTypeMap.get(skillType) || 0) + 1);
        });
      });
      const labels = Array.from(skillTypeMap.keys());
      const data = Array.from(skillTypeMap.values());
      if (labels.length > 0) {
        this.skillTypeChart = new Chart(ctx, {
          type: 'pie',
          data: {
            labels: labels,
            datasets: [{
              data: data,
              backgroundColor: ['#2196F3', '#FFC107', '#4CAF50', '#FF5722', '#9C27B0'],
              hoverBackgroundColor: ['#1976D2', '#FFA000', '#388E3C', '#E64A19', '#7B1FA2']
            }]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
              legend: {
                position: 'bottom'
              },
              tooltip: {
                callbacks: {
                  label: context => {
                    const label = context.label || '';
                    const value = context.parsed;
                    const total = context.dataset.data.reduce((sum, current) => sum + current, 0);
                    const percentage = total > 0 ? (value / total * 100).toFixed(1) : 0;
                    return `${label}: ${value} compétences (${percentage}%)`;
                  }
                }
              }
            }
          }
        });
      }
    }
  }
  createEmployeePositionChart() {
    if (this.employeePositionChart) {
      this.employeePositionChart.destroy();
      this.employeePositionChart = null;
    }
    const ctx = this.employeePositionChartRef?.nativeElement?.getContext('2d');
    if (ctx && this.employees.length > 0) {
      console.log('📊 Création du graphique postes employés');
      // Compter les employés par poste
      const positionCounts = new Map();
      this.employees.forEach(emp => {
        const position = emp.position || 'Non défini';
        positionCounts.set(position, (positionCounts.get(position) || 0) + 1);
      });
      const sortedPositions = Array.from(positionCounts.entries()).sort((a, b) => b[1] - a[1]).slice(0, 10); // Top 10 postes
      this.employeePositionChart = new Chart(ctx, {
        type: 'bar',
        data: {
          labels: sortedPositions.map(([position]) => position),
          datasets: [{
            label: 'Nombre d\'employés',
            data: sortedPositions.map(([, count]) => count),
            backgroundColor: '#2196F3',
            borderColor: '#1976D2',
            borderWidth: 1
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          scales: {
            y: {
              beginAtZero: true,
              ticks: {
                stepSize: 1
              }
            }
          },
          plugins: {
            legend: {
              display: false
            },
            tooltip: {
              callbacks: {
                label: context => {
                  return `${context.parsed.y} employé(s) dans ce poste`;
                }
              }
            }
          }
        }
      });
    }
  }
  createTrendsChart() {
    if (this.trendsChart) {
      this.trendsChart.destroy();
      this.trendsChart = null;
    }
    const ctx = this.trendsChartRef?.nativeElement?.getContext('2d');
    if (ctx) {
      console.log('📊 Création du graphique tendances');
      // Analyser les tendances par mois basées sur les vraies dates de création
      const monthlyData = this.calculateRealMonthlyTrends();
      this.trendsChart = new Chart(ctx, {
        type: 'line',
        data: {
          labels: monthlyData.map(d => d.month),
          datasets: [{
            label: 'Employés créés',
            data: monthlyData.map(d => d.employees),
            borderColor: '#3B82F6',
            backgroundColor: 'rgba(59, 130, 246, 0.1)',
            tension: 0.4,
            fill: true
          }, {
            label: 'Fiches de poste créées',
            data: monthlyData.map(d => d.jobDescriptions),
            borderColor: '#10B981',
            backgroundColor: 'rgba(16, 185, 129, 0.1)',
            tension: 0.4,
            fill: true
          }, {
            label: 'Offres d\'emploi créées',
            data: monthlyData.map(d => d.jobOffers),
            borderColor: '#F59E0B',
            backgroundColor: 'rgba(245, 158, 11, 0.1)',
            tension: 0.4,
            fill: true
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          scales: {
            y: {
              beginAtZero: true,
              ticks: {
                stepSize: 1
              }
            }
          },
          plugins: {
            legend: {
              position: 'top'
            },
            tooltip: {
              mode: 'index',
              intersect: false
            }
          }
        }
      });
    }
  }
  calculateRealMonthlyTrends() {
    const last6Months = [];
    const now = new Date();
    for (let i = 5; i >= 0; i--) {
      const date = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const nextMonth = new Date(now.getFullYear(), now.getMonth() - i + 1, 1);
      const monthName = date.toLocaleDateString('fr-FR', {
        month: 'short',
        year: '2-digit'
      });
      // Compter les vraies créations pour ce mois
      const employeesCount = this.employees.filter(emp => {
        if (!emp.createdAt) return false;
        const empDate = new Date(emp.createdAt);
        return empDate >= date && empDate < nextMonth;
      }).length;
      const jobDescriptionsCount = this.jobDescriptions.filter(job => {
        if (!job.createdAt) return false;
        const jobDate = new Date(job.createdAt);
        return jobDate >= date && jobDate < nextMonth;
      }).length;
      const jobOffersCount = this.jobOffers.filter(offer => {
        if (!offer.createdAt) return false;
        const offerDate = new Date(offer.createdAt);
        return offerDate >= date && offerDate < nextMonth;
      }).length;
      last6Months.push({
        month: monthName,
        employees: employeesCount,
        jobDescriptions: jobDescriptionsCount,
        jobOffers: jobOffersCount
      });
    }
    return last6Months;
  }
  destroyAllCharts() {
    const charts = [this.departmentChart, this.contractChart, this.skillsChart, this.trendsChart, this.employeePositionChart, this.skillTypeChart];
    charts.forEach(chart => {
      if (chart) {
        chart.destroy();
      }
    });
    this.departmentChart = null;
    this.contractChart = null;
    this.skillsChart = null;
    this.trendsChart = null;
    this.employeePositionChart = null;
    this.skillTypeChart = null;
  }
  exportReport(format) {
    console.log(`📄 Export du rapport en format ${format}`);
    // Générer les vraies données d'export
    const exportData = {
      overview: this.realTimeStats,
      departments: this.departmentStats,
      contracts: this.contractStats,
      skills: this.skillsDemand,
      employees_detail: this.employees.map(emp => ({
        id: emp.id,
        name: emp.name,
        position: emp.position,
        department: emp.department,
        hire_date: emp.hire_date,
        skills_count: (emp.skills || emp.EmployeeSkills || []).length
      })),
      job_descriptions_detail: this.jobDescriptions.map(job => ({
        id: job.id,
        emploi: job.emploi,
        filiere_activite: job.filiere_activite,
        famille: job.famille,
        required_skills_count: (job.requiredSkills || []).length
      })),
      job_offers_detail: this.jobOffers.map(offer => ({
        id: offer.id,
        title: offer.title,
        company: offer.company,
        status: offer.status,
        contract_type: offer.contract_type,
        salary_min: offer.salary_min,
        salary_max: offer.salary_max
      })),
      exportDate: new Date().toISOString(),
      filters_applied: this.filters
    };
    // Créer et télécharger le fichier
    const dataStr = format === 'csv' ? this.generateRealCSV(exportData) : JSON.stringify(exportData, null, 2);
    const blob = new Blob([dataStr], {
      type: format === 'csv' ? 'text/csv' : 'application/json'
    });
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `analytics-report-${new Date().toISOString().split('T')[0]}.${format === 'csv' ? 'csv' : 'json'}`;
    link.click();
    window.URL.revokeObjectURL(url);
  }
  generateRealCSV(data) {
    const headers = ['Métrique', 'Valeur', 'Détails'];
    const rows = [['Employés totaux', data.overview.totalEmployees, `Répartis sur ${this.departmentStats.length} départements`], ['Fiches de poste', data.overview.totalJobDescriptions, `${this.getMostActiveFiliere()} est la filière la plus active`], ['Offres d\'emploi totales', data.overview.totalJobOffers, ''], ['Offres publiées', data.overview.publishedOffers, `${this.getPublishedOffersPercentage().toFixed(1)}% du total`], ['Offres en brouillon', data.overview.draftOffers, ''], ['Offres fermées', data.overview.closedOffers, ''], ['Compétences uniques', data.overview.totalSkills, ''], ['Compétences par employé (moyenne)', data.overview.averageSkillsPerEmployee, ''], ['Poste le plus commun', data.overview.mostCommonPosition, ''], ['Filière la plus active', data.overview.mostActiveFiliere, '']];
    return [headers, ...rows].map(row => row.map(cell => `"${cell}"`).join(',')).join('\n');
  }
  // Méthodes utilitaires pour les templates
  getMostCommonPosition() {
    const positionCounts = new Map();
    this.employees.forEach(emp => {
      const position = emp.position || 'Non défini';
      positionCounts.set(position, (positionCounts.get(position) || 0) + 1);
    });
    let maxCount = 0;
    let mostCommon = 'Aucun';
    positionCounts.forEach((count, position) => {
      if (count > maxCount) {
        maxCount = count;
        mostCommon = position;
      }
    });
    return mostCommon;
  }
  getMostActiveFiliere() {
    const filiereMap = new Map();
    this.jobDescriptions.forEach(job => {
      const filiere = job.filiere_activite || 'Non défini';
      filiereMap.set(filiere, (filiereMap.get(filiere) || 0) + 1);
    });
    let maxCount = 0;
    let mostActive = 'Aucune';
    filiereMap.forEach((count, filiere) => {
      if (count > maxCount) {
        maxCount = count;
        mostActive = filiere;
      }
    });
    return mostActive;
  }
  getPublishedOffersPercentage() {
    if (this.jobOffers.length === 0) return 0;
    const published = this.jobOffers.filter(offer => offer.status === 'published').length;
    return published / this.jobOffers.length * 100;
  }
  // Méthodes pour les statistiques en temps réel
  getEmployeesWithCertifications() {
    return this.employees.filter(emp => {
      const skills = emp.skills || emp.EmployeeSkills || [];
      return skills.some(skill => skill.certification && skill.certification.trim() !== '');
    }).length;
  }
  getAverageHireTime() {
    if (this.employees.length === 0) return 0;
    const totalDays = this.employees.reduce((sum, emp) => {
      const hireDate = new Date(emp.hire_date);
      const daysSinceHire = Math.floor((Date.now() - hireDate.getTime()) / (1000 * 60 * 60 * 24));
      return sum + daysSinceHire;
    }, 0);
    return Math.round(totalDays / this.employees.length);
  }
  getSkillsGrowthRate() {
    // Calculer la croissance des compétences sur les 30 derniers jours
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
    let recentSkills = 0;
    let totalSkills = 0;
    this.employees.forEach(emp => {
      const skills = emp.skills || emp.EmployeeSkills || [];
      skills.forEach(skill => {
        totalSkills++;
        if (skill.acquired_date) {
          const acquiredDate = new Date(skill.acquired_date);
          if (acquiredDate >= thirtyDaysAgo) {
            recentSkills++;
          }
        }
      });
    });
    return totalSkills > 0 ? recentSkills / totalSkills * 100 : 0;
  }
};
